    53    54     0   55"

DF <- read.table(textConnection(Lines), header = TRUE)

nrow <-length(rownames(DF))
cnames <- colnames(DF)
nc <-length(DF)

nc.pairs <- nc*(nc-1)/2
#  initialize vector
cnames.new <- c(rep("",nc.pairs))
ind <- 1
print(sprintf("nc=%d",nc))
for (i in 1:(nc-1)) {
  if (i+1 <= nc ) {
    for (j in (i+1):nc) {
      cnames.new[ind] <- paste(cnames[i],cnames[j],sep="")
      ind <- ind+1
    }
  }
}

ind <- 1
